import buildData from './sitecontent.js';

/**
 * The URLs that differ between the Quarto site and this one, rendered as static
 * redirect pages.
 *
 * public/_redirects (generated by scripts/site/generate-redirects.mjs) covers
 * hosts that read it; these pages cover the ones that do not, GitHub Pages
 * among them. The rule is always the same: the Quarto URL is the one that has
 * been live for years, so it stays canonical and the new name points at it.
 */
export default function redirects() {
  return [
    { from: '/rss.html', to: '/rss.xml' },
    // Quarto has a standalone page at this URL. Its three identifiers are
    // already on /articles.html, so a separate page repeated them; the old URL
    // still has to resolve, because it has been published.
    { from: '/articles/profiles.html', to: '/articles.html' },
    { from: '/blog.html', to: '/posts.html' },
    // An earlier iteration served posts under /blog/. Those URLs were never
    // published, but they are cheap to keep resolving.
    ...buildData()
      .posts()
      .map((post) => ({ from: `/blog/${post.id}.html`, to: `/posts/${post.id}.html` })),
  ];
}
